import { useCallback, useEffect, useState } from "react";
import {
  fetchComplaints,
  createComplaint,
  assignWorkerToComplaint,
  updateComplaintStatus,
  closeComplaint,
} from "../../api/complaints.api";
import { fetchWorkers } from "../../api/admin.api";
import { useAuth } from "../../auth/AuthContext";

// Component Imports
import ComplaintCard from "../../components/complaints/ComplaintCard";
import RaiseComplaintModal from "../../components/complaints/RaiseComplaintModal";

export default function ComplaintsPage() {
  const { profile } = useAuth();

  const roleName = profile?.roles?.name || profile?.role || null;
  const isAdmin = roleName === "ADMIN";
  const isWorker = roleName === "WORKER";

  const [complaints, setComplaints] = useState([]);
  const [loading, setLoading] = useState(true);
  const [workers, setWorkers] = useState([]);
  const [selectedWorker, setSelectedWorker] = useState({});
  const [actionLoadingId, setActionLoadingId] = useState(null);

  const [statusFilter, setStatusFilter] = useState("");
  const [priorityFilter, setPriorityFilter] = useState("");

  // Modal State
  const [modalOpen, setModalOpen] = useState(false);

  // Form states
  const [category, setCategory] = useState("");
  const [description, setDescription] = useState("");
  const [priority, setPriority] = useState("LOW");
  const [error, setError] = useState("");

  const loadComplaints = useCallback(async () => {
    setLoading(true);
    setError("");
    try {
      const params = {};
      if (statusFilter) params.status = statusFilter;
      if (priorityFilter) params.priority = priorityFilter;

      const data = await fetchComplaints(params);
      setComplaints(data);
    } catch (err) {
      setError(err.message || "Failed to fetch complaints");
    } finally {
      setLoading(false);
    }
  }, [statusFilter, priorityFilter]);

  useEffect(() => {
    loadComplaints();
  }, [loadComplaints]);

  useEffect(() => {
    async function loadWorkersIfAdmin() {
      if (!isAdmin) return;
      try {
        const data = await fetchWorkers();
        setWorkers(data);
      } catch (err) {
        console.log("❌ workers fetch failed:", err.message);
      }
    }
    loadWorkersIfAdmin();
  }, [isAdmin]);

  async function handleAssignWorker(complaintId) {
    const worker_id = selectedWorker[complaintId];
    if (!worker_id) {
      setError("Please select a worker before assigning");
      return;
    }
    setActionLoadingId(complaintId);
    try {
      await assignWorkerToComplaint(complaintId, worker_id);
      await loadComplaints();
    } catch (err) {
      setError(err.message);
    } finally {
      setActionLoadingId(null);
    }
  }

  async function handleWorkerStatusUpdate(complaintId, nextStatus) {
    setActionLoadingId(complaintId);
    try {
      await updateComplaintStatus(complaintId, nextStatus);
      await loadComplaints();
    } catch (err) {
      setError(err.message);
    } finally {
      setActionLoadingId(null);
    }
  }

  async function handleCloseComplaint(complaintId) {
    setActionLoadingId(complaintId);
    try {
      await closeComplaint(complaintId);
      await loadComplaints();
    } catch (err) {
      setError(err.message);
    } finally {
      setActionLoadingId(null);
    }
  }

  async function handleCreateComplaint(e, modalData = null) {
    if (e && e.preventDefault) e.preventDefault();

    const cat = modalData?.category || category;
    const desc = modalData?.description || description;
    const pri = modalData?.priority || priority;

    if (!cat || !desc) {
      setError("Please fill all fields");
      return;
    }

    try {
      await createComplaint({ category: cat, description: desc, priority: pri });
      setCategory("");
      setDescription("");
      setPriority("LOW");
      setModalOpen(false);
      await loadComplaints();
    } catch (err) {
      setError(err.message || "Failed to create");
    }
  }

  return (
    <div className="max-w-[1600px] mx-auto p-6 space-y-6">

      {/* Page Header */}
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-800">
          Complaint Board <span className="text-sm font-medium text-indigo-600 bg-indigo-50 px-2 py-1 rounded-md ml-2">{roleName}</span>
        </h2>

        <div className="flex gap-3">
          <button 
            onClick={loadComplaints}
            className="bg-white border border-slate-200 text-slate-700 hover:bg-slate-50 px-4 py-2 rounded-lg font-medium transition-colors"
          >
            Refresh
          </button>

          <button
            onClick={() => setModalOpen(true)}
            className="bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2 rounded-lg font-medium transition-colors shadow-sm"
          >
            + Raise Complaint
          </button>
        </div>
      </div>

      {error && (
        <div className="bg-red-50 text-red-600 p-4 rounded-xl border border-red-100 font-medium">
          {error}
        </div>
      )}

      {/* Filters Section */}
      <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm flex flex-col sm:flex-row gap-4">
        <div className="flex-1">
          <label className="block text-sm font-medium text-slate-600 mb-1">Filter by Status</label>
          <select 
            value={statusFilter} 
            onChange={(e) => setStatusFilter(e.target.value)}
            className="w-full border border-slate-300 rounded-lg p-2.5 outline-none focus:ring-2 focus:ring-indigo-500 text-sm text-slate-700"
          >
            <option value="">All Statuses</option>
            <option value="NEW">NEW</option>
            <option value="ASSIGNED">ASSIGNED</option>
            <option value="IN_PROGRESS">IN_PROGRESS</option>
            <option value="RESOLVED">RESOLVED</option>
            <option value="CLOSED">CLOSED</option>
          </select>
        </div>

        <div className="flex-1">
          <label className="block text-sm font-medium text-slate-600 mb-1">Filter by Priority</label>
          <select 
            value={priorityFilter} 
            onChange={(e) => setPriorityFilter(e.target.value)}
            className="w-full border border-slate-300 rounded-lg p-2.5 outline-none focus:ring-2 focus:ring-indigo-500 text-sm text-slate-700"
          >
            <option value="">All Priorities</option>
            <option value="LOW">LOW</option>
            <option value="MEDIUM">MEDIUM</option>
            <option value="HIGH">HIGH</option>
            <option value="CRITICAL">CRITICAL</option>
          </select>
        </div>
      </div>

      {/* ✅ NEW: Kanban Status Board */}
      {loading ? (
        <p className="text-slate-500 py-10 text-center italic">Loading board...</p>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 items-start">
          {["NEW", "ASSIGNED", "IN_PROGRESS", "RESOLVED"].map((status) => (
            <div key={status} className="bg-slate-50 rounded-2xl p-4 border border-slate-200/60 min-h-[500px]">

              <div className="flex items-center justify-between mb-4 px-1">
                <h3 className="font-bold text-slate-700 text-sm tracking-wide uppercase">
                  {status.replace("_", " ")}
                </h3>
                <span className="bg-slate-200 text-slate-600 text-xs font-bold px-2 py-0.5 rounded-full">
                  {complaints.filter((c) => c.status === status).length}
                </span>
              </div>

              <div className="space-y-4">
                {complaints
                  .filter((c) => c.status === status)
                  .map((c) => (
                    <ComplaintCard
                      key={c.id}
                      complaint={c}
                      isAdmin={isAdmin}
                      isWorker={isWorker}
                      workers={workers}
                      selectedWorker={selectedWorker}
                      setSelectedWorker={setSelectedWorker}
                      handleAssignWorker={handleAssignWorker}
                      handleWorkerStatusUpdate={handleWorkerStatusUpdate}
                      handleCloseComplaint={handleCloseComplaint}
                      actionLoadingId={actionLoadingId}
                    />
                  ))}

                {complaints.filter((c) => c.status === status).length === 0 && (
                  <div className="text-center py-10 border-2 border-dashed border-slate-200 rounded-xl text-slate-400 text-xs italic">
                    No complaints
                  </div>
                )}
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Raise Complaint Modal */}
      <RaiseComplaintModal
        open={modalOpen}
        onClose={() => setModalOpen(false)}
        onSubmit={handleCreateComplaint}
      />
    </div>
  );
}
